-- Governance & Compliance Management System: deny-by-default relational core.
create extension if not exists pgcrypto;
create type app_role as enum ('general_manager','company_manager','compliance_officer','system_administrator','read_only');
create type task_status as enum ('unassigned','assigned','in_progress','submitted','overdue','closed');
create type compliance_status as enum ('compliant','action_required','not_verified','not_applicable');
create type review_status as enum ('pending_review','approved','returned','escalated');
create type action_status as enum ('open','in_progress','pending_verification','resolved','overdue');
create table public.user_profiles (id uuid primary key references auth.users(id) on delete restrict, display_name text not null, active boolean not null default true, created_at timestamptz not null default now());
create table public.companies (id uuid primary key default gen_random_uuid(), name_ar text not null, legal_name text, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.branches (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete restrict, name_ar text not null, active boolean not null default true, created_at timestamptz not null default now(), unique(company_id,name_ar));
create table public.user_company_roles (user_id uuid not null references public.user_profiles(id) on delete restrict, company_id uuid references public.companies(id) on delete restrict, role app_role not null, primary key(user_id,company_id,role));
create table public.user_branch_access (user_id uuid not null references public.user_profiles(id) on delete restrict, branch_id uuid not null references public.branches(id) on delete restrict, primary key(user_id,branch_id));
create table public.employees (id uuid primary key default gen_random_uuid(), employee_code text not null unique, company_id uuid not null references public.companies(id), branch_id uuid references public.branches(id), full_name text not null, job_title text, employment_status text not null, start_date date, owner_id uuid references public.user_profiles(id), created_at timestamptz not null default now());
create table public.compliance_items (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id), branch_id uuid references public.branches(id), name text not null, category text not null, authority text, applicable boolean not null default true, non_applicable_reason text, owner_id uuid references public.user_profiles(id), risk_level text not null default 'medium', evidence_required boolean not null default false, weekly_required boolean not null default true, active boolean not null default true, created_at timestamptz not null default now(), check (applicable or non_applicable_reason is not null));
create table public.licenses (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id), branch_id uuid references public.branches(id), license_type text not null, authority text not null, license_number text not null, issue_date date, expiry_date date not null, verified_status text not null default 'not_verified', last_verified_at timestamptz, verification_owner uuid references public.user_profiles(id), renewal_of uuid references public.licenses(id), created_at timestamptz not null default now(), unique(company_id,license_number));
create table public.contracts (id uuid primary key default gen_random_uuid(), employee_id uuid not null references public.employees(id), contract_identifier text not null unique, starts_at timestamptz not null, ends_at timestamptz, status text not null, verification_status text not null default 'not_verified', renewed_from uuid references public.contracts(id), last_verified_at timestamptz);
create table public.employee_events (id uuid primary key default gen_random_uuid(), employee_id uuid not null references public.employees(id), event_type text not null check(event_type in ('resignation','termination')), submitted_at timestamptz not null, expected_effective_at timestamptz, actual_effective_at timestamptz, process_status text not null, responsible_id uuid references public.user_profiles(id));
create table public.review_cycles (id uuid primary key default gen_random_uuid(), starts_on date not null, ends_on date not null, timezone text not null default 'Asia/Riyadh', unique(starts_on,ends_on), check(ends_on >= starts_on));
create table public.inspection_tasks (id uuid primary key default gen_random_uuid(), compliance_item_id uuid not null references public.compliance_items(id), review_cycle_id uuid not null references public.review_cycles(id), company_id uuid not null references public.companies(id), branch_id uuid references public.branches(id), assigned_to uuid references public.user_profiles(id), status task_status not null default 'unassigned', created_at timestamptz not null default now(), unique(compliance_item_id,review_cycle_id));
create table public.compliance_checks (id uuid primary key default gen_random_uuid(), inspection_task_id uuid not null unique references public.inspection_tasks(id), performed_by uuid references public.user_profiles(id), performed_at timestamptz, compliance_status compliance_status not null default 'not_verified', review_status review_status not null default 'pending_review', observation text, evidence_reference text, submitted_at timestamptz, check (compliance_status <> 'not_applicable' or observation is not null));
create table public.review_decisions (id uuid primary key default gen_random_uuid(), compliance_check_id uuid not null references public.compliance_checks(id), reviewer_id uuid not null references public.user_profiles(id), decision review_status not null, reason text, created_at timestamptz not null default now(), check(decision in ('approved','returned','escalated')));
create table public.corrective_actions (id uuid primary key default gen_random_uuid(), compliance_check_id uuid not null references public.compliance_checks(id), title text not null, assigned_to uuid references public.user_profiles(id), due_at timestamptz, priority text not null default 'medium', status action_status not null default 'open', resolution_notes text, resolved_at timestamptz, closure_reviewer uuid references public.user_profiles(id));
create table public.attachments (id uuid primary key default gen_random_uuid(), entity_type text not null, entity_id uuid not null, storage_path text not null unique, uploaded_by uuid references public.user_profiles(id), created_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), recipient_id uuid not null references public.user_profiles(id), event_type text not null, idempotency_key text not null unique, scheduled_at timestamptz not null, status text not null default 'scheduled', created_at timestamptz not null default now());
create table public.notification_delivery_attempts (id uuid primary key default gen_random_uuid(), notification_id uuid not null references public.notifications(id), attempted_at timestamptz not null default now(), provider_response text, status text not null);
create table public.audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references public.user_profiles(id), action text not null, entity_type text not null, entity_id uuid, before_value jsonb, after_value jsonb, correlation_id uuid, created_at timestamptz not null default now());
create table public.import_jobs (id uuid primary key default gen_random_uuid(), requested_by uuid references public.user_profiles(id), status text not null, created_at timestamptz not null default now());
create table public.import_errors (id uuid primary key default gen_random_uuid(), import_job_id uuid not null references public.import_jobs(id), row_number integer not null, message text not null);
create table public.scheduler_runs (id uuid primary key default gen_random_uuid(), job_name text not null, idempotency_key text not null unique, status text not null, details text, started_at timestamptz not null default now(), completed_at timestamptz);
create index on public.inspection_tasks(review_cycle_id,company_id,status); create index on public.licenses(expiry_date); create index on public.corrective_actions(due_at,status);

alter table public.companies enable row level security; alter table public.branches enable row level security; alter table public.compliance_items enable row level security; alter table public.inspection_tasks enable row level security; alter table public.compliance_checks enable row level security;
create function public.can_access_company(company uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from user_company_roles r where r.user_id=auth.uid() and (r.company_id=company or r.role in ('system_administrator','general_manager')))$$;
create policy company_access on public.companies for select using (public.can_access_company(id));
create policy branch_access on public.branches for select using (public.can_access_company(company_id));
create policy obligation_access on public.compliance_items for select using (public.can_access_company(company_id));
create policy task_access on public.inspection_tasks for select using (public.can_access_company(company_id));
create policy check_access on public.compliance_checks for select using (exists(select 1 from public.inspection_tasks t where t.id=inspection_task_id and public.can_access_company(t.company_id)));
-- Mutations are intentionally performed by reviewed RPCs/server code; no permissive write policy is added here.
